import { settings, saveSetting } from "../utils/settings";
const SETTING_KEY = "ramon-verified.document_types";
const FLUSH_DEBOUNCE_MS = 400;
/**
 * Owns the configurable list of accepted document types
 * (stored as a JSON-encoded array under the `ramon-verified.document_types`
 * setting key).
 */
export default class DocumentTypesState {
  types = [];
  _flushTimer = null;
  constructor() {
    this.types = this.parse(String(settings()[SETTING_KEY] ?? ""));
  }
  parse(raw) {
    if (!raw) return [];
    try {
      const parsed = JSON.parse(raw);
      return Array.isArray(parsed) ? parsed.filter(r => !!r && typeof r === "object").map(r => ({
        id: String(r.id || ""),
        label: String(r.label || "")
      })) : [];
    } catch (e) {
      return [];
    }
  }
  serialize() {
    return JSON.stringify(this.types.filter(r => r.id.trim() && r.label.trim()));
  }
  flushNow() {
    const raw = this.serialize();
    settings()[SETTING_KEY] = raw;
    saveSetting({
      [SETTING_KEY]: raw
    });
  }
  flushSoon() {
    if (this._flushTimer) clearTimeout(this._flushTimer);
    this._flushTimer = setTimeout(() => this.flushNow(), FLUSH_DEBOUNCE_MS);
  }
  add() {
    this.types = this.types.concat([{
      id: "",
      label: ""
    }]);
    m.redraw();
  }
  remove(idx) {
    this.types = this.types.filter((_, i) => i !== idx);
    this.flushNow();
    m.redraw();
  }
  update(idx, field, value) {
    this.types = this.types.map((r, i) => i === idx ? {
      ...r,
      [field]: value
    } : r);
    this.flushSoon();
    m.redraw();
  }
}
flarum.reg.add('ramon-verified', 'admin/states/DocumentTypesState', DocumentTypesState);